      END_STATE();
    case 109:
      ACCEPT_TOKEN(sym_line_comment);
      if (lookahead != 0 &&
          lookahead != '\n' &&
          lookahead != '\r') ADVANCE(109);
      END_STATE();
    case 110:
      ACCEPT_TOKEN(sym_doc_comment);
      END_STATE();
    case 111:
      ACCEPT_TOKEN(sym_block_comment);
      END_STATE();
    case 112:
      ACCEPT_TOKEN(sym_block_comment);
      if (lookahead == '*') ADVANCE(13);
      if (lookahead != 0) ADVANCE(14);
      END_STATE();
    default:
      return false;
